import React, { useState, useRef, useEffect, useCallback } from 'react';

const ImagePositionSelector = ({ imageUrl, initialPosition, onChange }) => {
  const containerRef = useRef(null);
  const [isDragging, setIsDragging] = useState(false);
  const [position, setPosition] = useState({ x: 50, y: 50 });
  const dragStartRef = useRef({ x: 0, y: 0 });

  // Parse initial position into x, y percentages
  useEffect(() => {
    if (initialPosition) {
      if (initialPosition.includes('%')) {
        const [x, y] = initialPosition.split(' ').map(val => 
          parseInt(val.replace('%', ''), 10)
        );
        if (!isNaN(x) && !isNaN(y)) {
          setPosition({ x, y });
        }
      } else {
        const positionMap = {
          'center': { x: 50, y: 50 },
          'top': { x: 50, y: 0 },
          'bottom': { x: 50, y: 100 },
          'left': { x: 0, y: 50 },
          'right': { x: 100, y: 50 },
          'top left': { x: 0, y: 0 },
          'top right': { x: 100, y: 0 },
          'bottom left': { x: 0, y: 100 },
          'bottom right': { x: 100, y: 100 }
        };
        setPosition(positionMap[initialPosition] || { x: 50, y: 50 });
      }
    }
  }, [initialPosition]);

  // Notify parent of position changes
  useEffect(() => {
    onChange(`${position.x}% ${position.y}%`);
  }, [position, onChange]);

  const updatePosition = useCallback((clientX, clientY) => {
    if (!containerRef.current || !isDragging) return;

    const rect = containerRef.current.getBoundingClientRect();
    const deltaX = clientX - dragStartRef.current.x;
    const deltaY = clientY - dragStartRef.current.y;

    const percentX = (deltaX / rect.width) * 100;
    const percentY = (deltaY / rect.height) * 100;

    setPosition(prev => ({
      x: Math.max(0, Math.min(100, prev.x - percentX)),
      y: Math.max(0, Math.min(100, prev.y - percentY))
    }));

    dragStartRef.current = { x: clientX, y: clientY };
  }, [isDragging]);

  const handleMouseDown = useCallback((e) => {
    e.preventDefault();
    setIsDragging(true);
    dragStartRef.current = { x: e.clientX, y: e.clientY };

    const handleMouseMove = (e) => {
      e.preventDefault();
      requestAnimationFrame(() => {
        updatePosition(e.clientX, e.clientY);
      });
    };

    const handleMouseUp = () => {
      setIsDragging(false);
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
    };

    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('mouseup', handleMouseUp);
  }, [updatePosition]);

  const handleTouchStart = useCallback((e) => {
    e.preventDefault();
    if (!e.touches[0]) return;

    setIsDragging(true);
    dragStartRef.current = { x: e.touches[0].clientX, y: e.touches[0].clientY };

    const handleTouchMove = (e) => {
      e.preventDefault();
      if (!e.touches[0]) return;

      requestAnimationFrame(() => {
        updatePosition(e.touches[0].clientX, e.touches[0].clientY);
      });
    };

    const handleTouchEnd = () => {
      setIsDragging(false);
      window.removeEventListener('touchmove', handleTouchMove);
      window.removeEventListener('touchend', handleTouchEnd);
    };

    window.addEventListener('touchmove', handleTouchMove, { passive: false });
    window.addEventListener('touchend', handleTouchEnd);
  }, [updatePosition]);

  const presetPositions = [
    { name: 'Center', x: 50, y: 50 },
    { name: 'Top', x: 50, y: 0 },
    { name: 'Bottom', x: 50, y: 100 },
    { name: 'Left', x: 0, y: 50 },
    { name: 'Right', x: 100, y: 50 }
  ];

  return (
    <div className="image-position-selector">
      <div className="position-preview-container">
        <div 
          ref={containerRef}
          className="position-preview"
          style={{
            backgroundImage: `url(${imageUrl})`,
            backgroundPosition: `${position.x}% ${position.y}%`,
            backgroundSize: 'cover',
            cursor: isDragging ? 'grabbing' : 'grab'
          }}
          onMouseDown={handleMouseDown}
          onTouchStart={handleTouchStart}
        >
          <div className="position-instructions">
            Drag to adjust image position
          </div>
        </div>
      </div>
      <div className="position-controls">
        <div className="position-presets">
          {presetPositions.map(preset => (
            <button 
              key={preset.name}
              type="button" 
              className="position-preset"
              onClick={() => setPosition(preset)}
            >
              {preset.name}
            </button>
          ))}
        </div>
        <div className="position-values">
          X: {Math.round(position.x)}%, Y: {Math.round(position.y)}%
        </div>
      </div>
    </div>
  );
};

export default ImagePositionSelector;
